// Der Story-Architekt bekommt pro Potenzial ein Item, wie in der Kette zuvor.
const rein = $input.first().json;
const p = rein.umschlag?.potenziale || [];
if (!p.length) throw new Error('Der Umschlag enthält keine Potenziale. Lief BC3-10 durch?');

/**
 * Vorgaben von BC3 je Kernprozess (seit 12.10.2026).
 *
 * Fuer UC2 (KP-05) misst der Soll-Ist-Vergleich den erzeugten Workflow am
 * Verhalten der handgebauten Referenz. Damit der Generator dieses Verhalten
 * ueberhaupt baut, muss es als Anforderung im Ticket stehen - der Generator
 * kennt nur die Tickets. Festlegung Svetlana 11.10.2026: die Referenz dient
 * als Checkliste. Uebernommen wird NUR das Verhalten, in eigenen Worten:
 * keine Fehlercodes, Feldnamen, Schwellwerte, Prompttexte oder Dateinamen
 * der Referenz (siehe Abschreibschutz in BC3-40).
 *
 * Die Nummern V1.. laufen wie A.. und K.. durch deckt_ab, die
 * Vollstaendigkeitspruefung, den Story-Ergaenzer und die Gate-2-Tabelle.
 */
const BC3_VORGABEN = {
  'KP-05': [
    'Antwort mit Quelle: Lässt sich eine Frage vollständig aus dem freigegebenen Bestand beantworten, gibt das System die Antwort zusammen mit Quellenangaben aus (Dokument, Abschnitt, Stand oder Version).',
    'Teilantwort: Lässt sich nur ein Teil der Frage belegen, beantwortet das System diesen Teil, kennzeichnet die Antwort ausdrücklich als Teilantwort und benennt, welcher Teil offen bleibt.',
    'Widerspruch: Widersprechen sich Quellen zur selben Frage, nennt das System alle widersprechenden Quellen und kennzeichnet den Widerspruch, statt sich für eine Fassung zu entscheiden.',
    'Kein Wissen im Bestand: Gibt der freigegebene Bestand keine belastbare Antwort her, sagt das System das ausdrücklich und erzeugt keine Antwort aus allgemeinem Modellwissen.',
    'Technischer Fehler ist kein Nichtwissen: Scheitert die Suche oder der Modellaufruf, meldet das System einen technischen Fehler und nicht "keine Antwort im Bestand".',
    'Ungültige Eingabe: Eine leere Frage oder eine Frage über der vereinbarten Höchstlänge wird mit einem verständlichen Hinweis zurückgewiesen, bevor gesucht wird.',
    'Belegtreue: Jede angegebene Quelle stammt aus den für diese Frage tatsächlich gefundenen Dokumenten, und wörtliche Zitate stehen genau so im Dokument.',
    'Status und Protokoll je Frage: Jede Antwort trägt genau einen Status aus der festen Liste beantwortet, teilweise beantwortet, Widerspruch, keine Antwort im Bestand, technischer Fehler, ungültige Eingabe. Status, genannte Quellen und eingesetzte Versionen werden je Frage protokolliert; fällt das Protokoll aus, wird die Antwort trotzdem mit einem Hinweis ausgegeben.',
    'Wiederholung und Aktualisierung des Index: Ein erneuter Indexlauf ohne Änderungen am Bestand verändert den Index nicht; ein geändertes Dokument ersetzt seine alte Fassung, sodass Antworten nur noch die neue Fassung zitieren.',
  ],
};

return p.map(x => ({
  json: {
    ...x,
    bc3_vorgaben: (BC3_VORGABEN[x.kp_id] || []).map((text, n) => ({ nr: `V${n + 1}`, text })),
  },
}));

