const items = $input.all();
const epics = [];
const fehler = [];

for (const item of items) {
  const raw = item.json.output;
  let cleaned = String(raw).trim();
  cleaned = cleaned.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```\s*$/i, '').trim();

  try {
    const epic = JSON.parse(cleaned);
    epics.push(epic);
  } catch (e) {
    fehler.push({ error: e.message, raw: String(raw).substring(0, 200) });
  }
}

const ucItems = $('Potenziale auspacken').all().map(i => i.json);
const erstesUcItem = ucItems[0];

// Kennungen über alle Use Cases einsammeln (Auflage BC0 vom 24.08.2026).
// Die Reihenfolge bleibt stabil, damit Läufe vergleichbar sind.
const alleTpIds = [...new Set(ucItems.flatMap(u => u.teilprozess_ids || []))];

// Epic i gehört zu Use Case i - die Story-Architekt-Items kommen in derselben
// Reihenfolge zurueck, in der sie hineingegeben wurden.
epics.forEach((epic, i) => {
  const uc = ucItems[i];
  if (uc && !epic.teilprozess_ids) {
    epic.teilprozess_ids = uc.teilprozess_ids || [];
  }
  // Saat fuer die Epic-ID (BC3-10, ab Vertrag 3.1). Der Final-Builder in
  // BC3-40 rechnet daraus die ID, damit ein Nachfolger sein Epic ersetzt.
  if (uc && uc.id_saat) epic.id_saat = uc.id_saat;
});

/**
 * Welche Datenarten kommen im Prozess vor, und wie schutzbeduerftig sind sie?
 *
 * Nicht jedes personenbezogene Datum wiegt gleich. Name und E-Mail brauchen
 * andere Massnahmen als eine Kontonummer oder ein Gesundheitsdatum - die DSGVO
 * unterscheidet das in Artikel 9 ausdruecklich. Wer das gleichsetzt, baut
 * entweder zu wenig Schutz oder einen Freigabepunkt an jeden Schritt, und das
 * zweite macht den Prozess unbrauchbar, ohne die Rechtslage zu verbessern.
 *
 * Erkannt wird nach Regeln, nicht vom Modell: die Einstufung muss bei jedem
 * Lauf gleich ausfallen und im Nachhinein nachlesbar sein. Der Compliance-Agent
 * bekommt das Ergebnis als Vorgabe und darf ergaenzen, nicht ueberstimmen.
 */
const DATEN_REGELN = [
  // Stufe hoch: DSGVO Art. 9 und alles, was unmittelbar Geld oder Zugang bewegt
  { art: 'Gesundheitsdaten',      stufe: 'hoch',   muster: /gesundheit|krank|diagnos|arbeitsunf(ä|ae)hig|attest|therapie|medizin/i },
  { art: 'Zahlungs- und Kontodaten', stufe: 'hoch', muster: /kontonummer|\biban\b|\bbic\b|kreditkarte|zahlungsdat|bankverbindung|lastschrift/i },
  { art: 'Biometrische Daten',    stufe: 'hoch',   muster: /biometri|fingerabdruck|gesichtserkennung|stimmerkennung/i },
  { art: 'Bewertungen von Personen', stufe: 'hoch', muster: /eignung|bewert(ung|et) (von )?(bewerber|mitarbeit|person)|ranking|scoring|bonit(ä|ae)t|leistungsbeurteil|matching.?score/i },
  { art: 'Bewerbungsunterlagen',  stufe: 'hoch',   muster: /lebenslauf|bewerbungsunterlag|bewerberdat|zeugnis|cv\b/i },
  // \b vor gehalt, sonst trifft es "festgehalten" - im Test gegen UC2 passiert
  { art: 'Gehalts- und Vertragsdaten', stufe: 'hoch', muster: /\bgeh(a|ä|ae)lt(er|s|es)?\b|gehaltsdat|verg(ü|ue)tung|honorar|arbeitsvertrag|k(ü|ue)ndigung/i },
  { art: 'Zugangsdaten',          stufe: 'hoch',   muster: /passwort|zugangsdaten|api.?key|token|anmeldedaten/i },
  // Stufe gering: personenbezogen, aber mit Pseudonymisierung oder EU-Verarbeitung beherrschbar
  { art: 'Name',                  stufe: 'gering', muster: /\bname\b|vorname|nachname|ansprechpartner/i },
  { art: 'E-Mail-Adresse',        stufe: 'gering', muster: /e-?mail|\bmails?\b|postfach|mailadresse/i },
  { art: 'Telefonnummer',         stufe: 'gering', muster: /telefon|mobilnummer|durchwahl/i },
  { art: 'Dienstliche Anschrift', stufe: 'gering', muster: /anschrift|adresse|standort des b(ü|ue)ros/i },
  { art: 'Reise- und Termindaten', stufe: 'gering', muster: /reiseziel|reisedat|abflug|hotel|buchungsdat|zeitraum|termin/i },
  { art: 'Kostenstelle und Budget', stufe: 'gering', muster: /kostenstelle|budget|reisekosten|spesen/i },
];

// Durchsucht wird, was BC2 wirklich geschrieben hat - nicht die Epics des
// Modells. Sonst pruefen wir unsere eigene Erfindung. Die Feldnamen sind die
// von BC3-10 nach der Umbenennung, nicht die des Rohkonzepts.
function texte(u) {
  const roh = [
    u.use_case_titel, u.fachliche_beschreibung, u.to_be_vision, u.prozess, u.warnung,
    ...(u.betroffene_prozessschritte || []),
    ...(u.fachliche_anforderungen || []),
    ...(u.voraussetzungen || []),
    // Ab v3.1 sind die Kriterien Objekte (kriterium, messverfahren), vorher Text
    ...(u.akzeptanzkriterien_geschaeftlich || []).map(a =>
      typeof a === 'string' ? a : [a?.kriterium, a?.messverfahren].filter(Boolean).join(' ')),
    ...(u.schmerzpunkte || []).map(s => s?.beschreibung ?? s),
    ...(u.risiken || []).map(r => [r?.beschreibung, r?.gegenmassnahme].filter(Boolean).join(' ')),
    ...(u.annahmen || []),
  ];
  return roh.filter(x => typeof x === 'string' && x.trim());
}

/**
 * Gesucht wird in echten Saetzen, nicht in JSON.
 *
 * Erst hiess es JSON.stringify(...) und danach ein Split am Satzzeichen. In
 * einem JSON-Text kommt kaum ein Satzende vor, also war jeder "Satz" ein
 * Klumpen von hunderten Zeichen: die Verneinungspruefung fiel in sich zusammen,
 * weil irgendwo im Klumpen immer ein "nicht" steht, und der Beleg war fuer
 * einen Menschen nicht lesbar. Der Beleg ist aber der einzige Grund, warum ein
 * Mensch die Einstufung nachpruefen kann.
 */
const saetze = ucItems
  .flatMap(texte)
  .flatMap(t => t.split(/(?<=[.!?;])\s+|\n+/))
  .map(s => s.trim())
  .filter(s => s.length > 3);

const quelltext = saetze.join(' ');

/**
 * Steht die Datenart im Konzept, oder steht dort, dass sie NICHT vorkommt?
 *
 * In UC3 taucht "Bewertung von Personen" nur in Saetzen auf, die sie
 * ausschliessen: "Automatisiert wird das Auslesen der Angaben, nicht die
 * Bewertung von Personen." BC2 hat diese Entscheidung getroffen. Eine Auflage
 * gegen etwas, das gar nicht gebaut wird, kostet BC4 Arbeit und schuetzt
 * niemanden.
 *
 * Kommt eine Datenart AUSSCHLIESSLICH in verneinten Saetzen vor, gilt sie als
 * ausgeschlossen - nicht als uebersehen. Der Fall geht nicht verloren, sondern
 * wird eigens ausgewiesen: er begruendet, warum die Klasse nicht hoeher
 * ausfaellt. Sobald derselbe Begriff einmal ohne Verneinung vorkommt, zaehlt er
 * normal. Im Zweifel also erkannt, nicht ausgeschlossen.
 */
/**
 * Verneint dieser Satz die Datenart wirklich - oder steht nur irgendwo ein
 * Verneinungswort?
 *
 * Die erste Fassung vom 04.09.2026 suchte IRGENDWO im Satz und fiel damit auf
 * BC2s Schreibweise herein. Vier Rollen der Diskussionsrunde haben es gemeldet,
 * die Gegenprobe an den echten Konzepten hat es bestaetigt. Drei Faelle, die
 * jetzt richtig laufen:
 *
 *   "Der Vorgang bleibt offen, wenn kein Budget angegeben ist, und das
 *    Reiseziel wird trotzdem gespeichert."
 *      "kein" gehoert zum Budget, nicht zum Reiseziel. Deshalb wird im
 *      SATZGLIED geprueft, nicht in einem Zeichenfenster.
 *
 *   "Unklare Angaben werden markiert statt geraten."
 *      "statt" kennzeichnet eine Ersetzung, keine Verneinung des Gegenstands -
 *      und ist ein Lieblingswort von BC2. Steht nicht mehr in der Liste.
 *
 *   "Gegeben eine Anfrage ohne Reisedatum, wenn sie verarbeitet wird, dann
 *    geht eine Rueckfrage an die anfragende Person."
 *      Ein Given/When/Then-Kriterium. "ohne X" beschreibt den Eingangsfall
 *      eines Tests; der Satz ist die Vorschrift dafuer, wie mit einem
 *      FEHLENDEN Reisedatum umzugehen ist - Reisedaten kommen also vor.
 *      In solchen Saetzen zaehlt "ohne" nicht.
 *
 * Im Zweifel gilt: nicht ausgeschlossen. Ein zu viel erkanntes Datum kostet
 * eine Auflage zu viel, ein zu wenig erkanntes kostet den Schutz.
 */
const VERNEINT = /\b(nicht|keine[rmns]?|kein|ausgeschlossen|unterbleibt?|verzicht\w*|untersagt|niemals|unzul(ae|ä)ssig)\b/i;
const OHNE_DAVOR = /\bohne\s+(\w+\s+){0,2}$/i;
// Given/When/Then in den Schreibweisen, die BC2 verwendet
const KRITERIUM = /^\s*(gegeben|given|angenommen|wenn\b)/i;

/**
 * Zerlegt in Satzglieder. Eine Verneinung wirkt bis zum naechsten Komma oder
 * bis zur naechsten Konjunktion - "und das Reiseziel wird trotzdem
 * gespeichert" ist ein eigenes Glied.
 */
function glieder(satz) {
  return satz.split(/[,;:]|\s+(?:und|oder|aber|sondern|dann|sodass|damit|wobei|waehrend|während)\s+/i)
    .map(t => t.trim()).filter(Boolean);
}

function verneint(satz, muster) {
  const istKriterium = KRITERIUM.test(satz);
  for (const glied of glieder(satz)) {
    const m = glied.match(muster);
    if (!m) continue;
    if (VERNEINT.test(glied)) return true;
    // "ohne" nur unmittelbar vor dem Begriff - und nicht in einem
    // Given/When/Then, wo es den Eingangsfall beschreibt
    if (!istKriterium && OHNE_DAVOR.test(glied.slice(0, m.index))) return true;
  }
  return false;
}

function einordnen(regel) {
  const treffer = saetze.filter(s => regel.muster.test(s));
  if (!treffer.length) return null;
  const bejaht = treffer.filter(s => !verneint(s, regel.muster));
  return {
    art: regel.art,
    stufe: regel.stufe,
    ausgeschlossen: bejaht.length === 0,
    // Ein Satz, den ein Mensch lesen und gegen das Konzept halten kann
    beleg: (bejaht[0] || treffer[0]).slice(0, 200),
    fundstellen: treffer.length,
  };
}

const alleTreffer = DATEN_REGELN.map(einordnen).filter(Boolean);
const gefunden = alleTreffer.filter(d => !d.ausgeschlossen)
  .map(({ art, stufe, beleg, fundstellen }) => ({ art, stufe, beleg, fundstellen }));
const ausgeschlossen = alleTreffer.filter(d => d.ausgeschlossen)
  .map(({ art, stufe, beleg, fundstellen }) => ({ art, stufe, beleg, fundstellen }));
const hoch = gefunden.filter(d => d.stufe === 'hoch');

/**
 * Wie schwer wiegt die Entscheidung, die hier automatisiert wird?
 *
 * Das ist eine ANDERE Frage als die nach der Datenkategorie, und sie wurde bis
 * zum 04.09.2026 mit ihr verwechselt. Bei UC1 erkannte die Datentabelle
 * ausschliesslich Stufe gering - Name, E-Mail, Reiseziel - und daraus wurde
 * "eine menschliche Pruefung waere unverhaeltnismaessig". UC1 ist aber
 * Einsatzplanung, also Aufgabenzuweisung, und die steht in Anhang III Nr. 4
 * Buchstabe b. Artikel 22 DSGVO haengt genauso an der WIRKUNG der Entscheidung
 * auf die betroffene Person, nicht an der Sensibilitaet des Feldes.
 *
 * Ein Prozess mit harmlosen Daten und schwerwiegender Entscheidung waere damit
 * ohne Aufsichtspunkt durchgelaufen. Von allen Fehlern, die dieses Bauteil
 * machen kann, ist das der teuerste, weil er in Richtung "zu wenig Schutz"
 * zeigt.
 *
 * Seit 13.10.2026 zwei Stufen je Regel (Entscheidung Svetlana: richtig
 * einordnen, nicht pauschal hochstufen). Im Lauf 438 (UC2, Wissenssuche) wurde
 * Hochrisiko allein aus "die abschliessende Beurteilung ... beim Menschen" und
 * "Zugang zu Inhalten" abgeleitet.
 * - muster: eindeutig eine Entscheidung ueber Personen -> Stufe "erheblich"
 * - unsicher: nur das Stichwort -> Stufe "zu pruefen". Das geht NICHT verloren,
 *   sondern steht mit Beleg an Gate 2 und beim Compliance-Agenten, der die
 *   Einordnung begruenden muss. Im Zweifel also sichtbar, nicht hochgestuft.
 */
const TRAGWEITE_REGELN = [
  { art: 'Auswahl oder Einstellung von Personen', anhang: 'Anhang III Nr. 4 Buchstabe a',
    muster: /bewerb\w*|einstellung|personalauswahl|vorauswahl|kandidat\w*|besetzung|recruit/i },
  { art: 'Zuweisung von Aufgaben oder Einsaetzen', anhang: 'Anhang III Nr. 4 Buchstabe b',
    muster: /einsatzplan\w*|einsatz\w*zuweis|aufgabenzuweis|aufgaben\w*vertei|disponier\w*|zuteil\w*|einteil\w*|besetzungsvorschlag|zuordnung von (mitarbeit|berater|consultant|personal)/i },
  { art: 'Bewertung von Leistung oder Eignung', anhang: 'Anhang III Nr. 4 Buchstabe b',
    muster: /leistungsbeurteil\w*|(mitarbeiter|personal)beurteil\w*|beurteil\w* (von|der|des) (person|mitarbeit|besch(ä|ae)ftigt|bewerber|kandidat|leistung)|eignung\w*|bewertung von (person|mitarbeit|bewerber|leistung)|scoring|ranking (von|der) (person|bewerber|kandidat|mitarbeit)|matching\W?score/i,
    unsicher: /beurteil\w*|ranking/i },
  { art: 'Beendigung oder Befristung eines Vertrags', anhang: 'Anhang III Nr. 4 Buchstabe b',
    muster: /k(ü|ue)ndig\w*|befristung|vertragsende|entlass\w*|abmahn\w*/i },
  { art: 'Verguetung oder Befoerderung', anhang: 'Anhang III Nr. 4 Buchstabe b',
    muster: /bef(ö|oe)rder\w*|geh(a|ä|ae)ltsentscheid|verg(ü|ue)tungsentscheid|pr(ä|ae)mie|bonusentscheid/i },
  { art: 'Zugang zu einer Leistung oder einem Vertrag', anhang: 'Artikel 22 DSGVO',
    muster: /bonit(ä|ae)t|kreditentscheid|antrag (wird )?(automatisch )?(bewilligt|abgelehnt)|ablehnung des antrags|zugang zu (einer |einem |der |den )?(leistung|vertrag|kredit|sozialleistung|versicherung|wohnung|ausbildung|studium)/i,
    unsicher: /zugang zu/i },
  { art: 'Geldwirksame Entscheidung', anhang: 'Artikel 22 DSGVO, erhebliche Wirkung',
    muster: /buchung ausl(ö|oe)s\w*|bestellung ausl(ö|oe)s\w*|zahlung ausl(ö|oe)s\w*|storn\w*|verbindlich\w* (buch|bestell)/i },
];

const pruefeMuster = (r, muster) => {
  const treffer = saetze.filter(s => muster.test(s));
  if (!treffer.length) return null;
  // Dieselbe Naehepruefung wie bei den Datenarten, nicht irgendwo im Satz
  const bejaht = treffer.filter(s => !verneint(s, muster));
  return {
    art: r.art, anhang: r.anhang,
    ausgeschlossen: bejaht.length === 0,
    beleg: (bejaht[0] || treffer[0]).slice(0, 200),
  };
};

const tragweiteTreffer = TRAGWEITE_REGELN.map(r => pruefeMuster(r, r.muster)).filter(Boolean);
const tragend = tragweiteTreffer.filter(x => !x.ausgeschlossen);
// Nur das Stichwort, keine eindeutige Entscheidung ueber Personen
const unsicher = TRAGWEITE_REGELN
  .filter(r => r.unsicher && !tragend.some(t => t.art === r.art))
  .map(r => pruefeMuster(r, r.unsicher))
  .filter(x => x && !x.ausgeschlossen);

const tragweite = {
  stufe: tragend.length ? 'erheblich' : (unsicher.length ? 'zu pruefen' : 'keine erkannt'),
  erkannt: tragend.map(({ art, anhang, beleg }) => ({ art, anhang, beleg })),
  zu_pruefen: unsicher.map(({ art, anhang, beleg }) => ({ art, anhang, beleg })),
  ausdruecklich_ausgeschlossen: tragweiteTreffer.filter(x => x.ausgeschlossen)
    .map(({ art, anhang, beleg }) => ({ art, anhang, beleg })),
  als_text: [
    ...tragend.map(x => `${x.art} (${x.anhang}) - Beleg: "${x.beleg}"`),
    ...unsicher.map(x => `UNSICHER, nur Stichwort: ${x.art} (${x.anhang}) - Beleg: "${x.beleg}"`),
  ],
  hinweis: tragend.length
    ? `Der Prozess entscheidet ueber Personen: ${tragend.map(x => x.art).join('; ')}. `
      + `Damit ist eine menschliche Entscheidung an der Stelle erforderlich, an der `
      + `diese Entscheidung faellt - UNABHAENGIG davon, wie harmlos die verarbeiteten `
      + `Datenarten sind. Artikel 22 DSGVO und Anhang III haengen an der Wirkung auf `
      + `die betroffene Person, nicht an der Sensibilitaet des Feldes.`
    : unsicher.length
      ? `Keine eindeutige Entscheidung ueber Personen erkannt, nur Stichworte (siehe UNSICHER). `
        + `Ein Stichwort allein begruendet KEIN Hochrisiko. Stufe nur dann nach Anhang III ein, `
        + `wenn die Epics tatsaechlich ueber Auswahl, Einsatz, Leistung, Vertrag oder Zugang `
        + `einer Person entscheiden, und nenne in begruendung_ampel die Stelle. Sonst minimal `
        + `oder limited.`
      : `Keine Entscheidung ueber Personen erkannt. Wenn die Epics dennoch eine `
        + `treffen, gilt fuer sie dasselbe.`,
};

const datenarten = {
  erkannt: gefunden,
  // Im Konzept genannt, aber ausdruecklich ausgeschlossen. Das ist der Grund,
  // warum die Klasse nicht hoeher ausfaellt - und gehoert deshalb in die Akte.
  ausdruecklich_ausgeschlossen: ausgeschlossen,
  hoechste_stufe: hoch.length ? 'hoch' : (gefunden.length ? 'gering' : 'keine erkannt'),
  // Fuer den Prompt: eine Zeile je Datenart, damit der Agent sie zitieren kann
  als_text: gefunden.map(d => `${d.art} (Stufe ${d.stufe})`),
  ausschluss_text: ausgeschlossen.map(d =>
    `${d.art}: laut Konzept ausdruecklich nicht vorgesehen - "${d.beleg}"`),
  hinweis: hoch.length
    ? `Stufe hoch erkannt (${hoch.map(d => d.art).join(', ')}). An den Stellen, an `
      + `denen diese Daten eine Entscheidung beeinflussen, gehoert eine menschliche `
      + `Pruefung dazu. Fuer die uebrigen Daten genuegen Pseudonymisierung oder `
      + `EU-Verarbeitung.`
    : gefunden.length
      ? `Nur Daten der Stufe gering erkannt. Fuer den SCHUTZ DER DATEN genuegt `
        + `Pseudonymisierung der Kontaktdaten vor dem Modellaufruf oder Verarbeitung `
        + `in der EU. Das sagt nichts darueber, ob ein Mensch entscheiden muss - `
        + `dafuer ist die Tragweite der Entscheidung zustaendig, siehe eigenes Feld.`
      : `Keine personenbezogenen Datenarten in der Beschreibung erkannt. Das heisst `
        + `nicht, dass keine vorkommen - der Agent prueft die Epics zusaetzlich.`,
};

return [{
  json: {
    konzept_id: erstesUcItem.konzept_id,
    schema_version: erstesUcItem.schema_version,
    prozess: erstesUcItem.prozess,
    schmerzpunkte: erstesUcItem.schmerzpunkte,
    original_filename: erstesUcItem.original_filename,
    kp_id: erstesUcItem.kp_id,
    teilprozess_ids: alleTpIds,
    value_quelle: erstesUcItem.value_quelle,
    // Risiken aller Potenziale zusammen, damit BC3-30 sie im Prompt hat.
    // Doppelte fallen raus: BC2 nennt dieselbe Sorge oft in mehreren Potenzialen.
    risiken: (() => {
      const gesehen = new Set();
      return ucItems.flatMap(u => u.risiken || []).filter(r => {
        const s = String(r.beschreibung || '').trim().toLowerCase();
        if (!s || gesehen.has(s)) return false;
        gesehen.add(s);
        return true;
      });
    })(),
    // Nach Regeln erkannt, damit die Einstufung bei jedem Lauf gleich ausfaellt
    datenarten: datenarten,
    // Zweite Achse: die Datenkategorie sagt, WIE zu schuetzen ist, die
    // Tragweite sagt, OB ein Mensch entscheiden muss. Bis zum 04.09. wurde
    // nur die erste beantwortet und die Antwort fuer beide ausgegeben.
    tragweite: tragweite,
    ist_vorlaeufig: ucItems.some(u => u.ist_vorlaeufig === true),
    anzahl_epics: epics.length,
    epics: epics,
    fehler: fehler.length > 0 ? fehler : undefined
  }
}];

/**
 * Vollständigkeitsprüfung — läuft NACH dem Story-Architekten.
 *
 * Fängt genau die Fehlerklasse ab, die BC3 am 20.08. in BC4s Generator
 * gefunden hat (K8): Einträge verschwinden lautlos in der Übersetzung.
 *
 * Seit 11.10.2026: Fehlende Anforderungen (A..) und Kriterien (K..) brechen
 * hier NICHT ab, sondern gehen als luecken an den Story-Ergänzer. Erst wenn
 * auch der zweite Durchgang Lücken lässt, bricht "Ergänzung einfügen" ab.
 * Seit 12.10.2026 zaehlen auch die Vorgaben von BC3 (V..) dazu. Und eine
 * Nummer, die eine Story zwar beansprucht, deren Inhalt dort aber praktisch
 * fehlt (unter INHALT_MIN), geht ebenfalls an den Story-Ergaenzer - im Lauf
 * 419 beanspruchte "Vektorbasierte Suche" die Zugriffsrechte, ohne sie zu
 * enthalten, und eine Story dazu gab es nicht.
 * Meldungen stehen in EINER Zeile - n8n gibt dem Orchestrator nur die erste
 * Zeile einer Fehlermeldung weiter.
 */
const a = JSON.parse(JSON.stringify($input.first().json));
const eingaenge = $('Potenziale auspacken').all().map(i => i.json);
const hart = [];
const weich = [];

// --- Inhaltlicher Abgleich ueber Wortteile (seit 12.10.2026) ----------------
// DIESELBE Regel steht in BC3-00 'Abdeckung anhaengen' (Gate-2-Tabelle).
// Wer sie aendert, aendert sie an beiden Stellen - sonst meldet Gate 2 etwas
// anderes als die Vollstaendigkeitspruefung.
const FUELL = new Set(['eine', 'einer', 'einem', 'einen', 'eines', 'wird', 'werden', 'wurde', 'nicht',
  'oder', 'sowie', 'dass', 'wenn', 'dann', 'sind', 'ihre', 'ihren', 'alle', 'allen', 'mehr', 'nach',
  'ueber', 'über', 'durch', 'beim', 'given', 'when', 'then', 'gegeben', 'diese', 'dieser', 'dieses',
  'kann', 'muss', 'soll', 'damit', 'auch', 'noch', 'sich', 'etwa', 'jede', 'jeder', 'jedes', 'mindestens',
  'system', 'systems', 'story']);
const woerter = s => [...new Set(String(s || '').toLowerCase()
  .replace(/ß/g, 'ss')
  .replace(/[^a-zäöü0-9 ]+/g, ' ').split(/\s+/)
  .filter(x => x.length > 3 && !FUELL.has(x)))];
const DREIER = new Map();
const dreierVon = w => {
  if (!DREIER.has(w)) { const s = ` ${w} `; const g = new Set(); for (let i = 0; i < s.length - 2; i++) g.add(s.slice(i, i + 3)); DREIER.set(w, g); }
  return DREIER.get(w);
};
function wortGleich(a, b) {
  if (a === b) return true;
  if (Math.min(a.length, b.length) >= 5 && (a.startsWith(b) || b.startsWith(a))) return true;
  // Wortende (seit 13.10.2026): Zusammensetzungen wie 'Vorschlagsliste' / 'Liste'.
  if (Math.min(a.length, b.length) >= 5 && (a.endsWith(b) || b.endsWith(a))) return true;
  const A = dreierVon(a), B = dreierVon(b);
  let g = 0; for (const x of A) if (B.has(x)) g++;
  return (2 * g) / (A.size + B.size) >= 0.6;
}
function anteil(quelle, ziel) {
  const q = woerter(quelle), z = woerter(ziel);
  if (!q.length) return 1;
  let treffer = 0;
  for (const w of q) if (z.some(x => wortGleich(w, x))) treffer++;
  return treffer / q.length;
}
const storyText = s => [s.titel, s.beschreibung,
  ...(s.akzeptanzkriterien || []).map(k => `${k.text || ''} ${k.messverfahren || ''}`)].join(' ');
// Unter diesem Anteil gilt eine beanspruchte Nummer als inhaltlich NICHT
// abgedeckt und geht an den Story-Ergaenzer. Geeicht an den Laeufen 388, 395,
// 402 und 419: echte Fehlzuordnungen lagen bei 0-17 %, tragfaehige ab 29 %.
const INHALT_MIN = 0.2;

// 1. Hat der Aggregations-Baustein Parse-Fehler verschluckt?
if (a.fehler && a.fehler.length) {
  hart.push(`Der Story-Architekt hat ${a.fehler.length} Antwort(en) geliefert, die sich nicht lesen liessen. Erste: ${a.fehler[0].error}`);
}

// 2. Kam aus jedem Potenzial ein Epic?
if (a.anzahl_epics !== eingaenge.length) {
  hart.push(`${eingaenge.length} Potenzial(e) hinein, ${a.anzahl_epics} Epic(s) heraus. Es ist etwas verlorengegangen.`);
}

// 3. Hat jedes Epic Stories, und hat jede Story Kriterien?
// Seit 22.10.2026 (Vorschlag 4): Eine Story ohne Kriterium (oft, weil
// "Kriterien reparieren" das einzige entfernt hat) bricht nicht mehr ab. Sie
// wird entfernt, das Ticket-Schema verlangt mindestens ein Kriterium. Ihre
// Nummern aus deckt_ab fehlen dann und gehen unten als Lücke an den
// Story-Ergänzer. Fehlen sie nach dem zweiten Durchgang noch, bricht
// "Ergänzung einfügen" ab.
let storiesGesamt = 0;
let ohneKriterium = 0;
(a.epics || []).forEach((e, i) => {
  const st = e.stories || [];
  if (st.length === 0) hart.push(`Epic ${i + 1} ("${String(e.titel || '').slice(0, 40)}") hat keine einzige Story.`);
  st.forEach((s, j) => {
    if (!s.titel || !s.beschreibung) hart.push(`Epic ${i + 1}, Story ${j + 1}: Titel oder Beschreibung fehlt.`);
  });
  e.stories = st.filter(s => {
    if ((s.akzeptanzkriterien || []).length) return true;
    ohneKriterium++;
    const nr = (Array.isArray(s.deckt_ab) ? s.deckt_ab : []).join(', ');
    weich.push(`Epic ${i + 1}: Story „${String(s.titel || s.story_id || '').slice(0, 60)}“ ohne Kriterium entfernt`
      + (nr ? `, ${nr} an den Story-Ergänzer.` : ', sie deckte keine Nummer ab.'));
    return false;
  });
  storiesGesamt += e.stories.length;
});

// 5. Wie viel vom Eingang ist angekommen?
const anfGesamt = eingaenge.reduce((s, e) => s + (e.fachliche_anforderungen || []).length, 0);
const akzGesamt = eingaenge.reduce((s, e) => s + (e.akzeptanzkriterien_geschaeftlich || []).length, 0);
const vorgGesamt = eingaenge.reduce((s, e) => s + (e.bc3_vorgaben || []).length, 0);

// 6. Ist jede Anforderung (A1..), jedes Kriterium (K1..) und jede Vorgabe von
// BC3 (V1..) in einer Story? Der Story-Architekt nennt je Story in deckt_ab,
// welche Nummern sie abdeckt. Bis zum 11.10.2026 wurde nur die Stueckzahl
// gezaehlt - im Lauf gegen KP-05 fehlten so zwei von sechs Anforderungen,
// ohne dass es auffiel. Epic i gehoert zu Potenzial i, siehe Epics aggregieren.
const text = t => typeof t === 'string' ? t
  : [t?.kriterium, t?.messverfahren ? `Messverfahren: ${t.messverfahren}` : null].filter(Boolean).join(' ');
const luecken = [];
(a.epics || []).forEach((e, i) => {
  const ein = eingaenge[i];
  if (!ein) return;
  const soll = new Map([
    ...(ein.fachliche_anforderungen || []).map((x, n) => [`A${n + 1}`, text(x)]),
    ...(ein.akzeptanzkriterien_geschaeftlich || []).map((x, n) => [`K${n + 1}`, text(x)]),
    ...(ein.bc3_vorgaben || []).map(v => [v.nr, v.text]),
  ]);
  const ist = new Set((e.stories || [])
    .flatMap(s => Array.isArray(s.deckt_ab) ? s.deckt_ab : [])
    .map(x => String(x).trim().toUpperCase()));
  // Seit 23.10.2026 (C9, N2): Nennt eine Story die Nummer nicht in deckt_ab,
  // aber ausdrücklich in einem Kriterium („K2: …“ im Messverfahren) und passt
  // der Inhalt, gilt sie als abgedeckt. Vorher schrieb der Story-Ergänzer dazu
  // eine zweite Story mit demselben Kriterium (KP-05 Lauf 2331, Stories 2 und 7).
  for (const k of [...soll.keys()].filter(k => !ist.has(k))) {
    const marke = new RegExp(`(^|[^A-Za-z0-9])${k}([^0-9]|$)`);
    const traeger = (e.stories || []).find(s => (s.akzeptanzkriterien || [])
      .some(x => marke.test(`${x.text || ''} ${x.messverfahren || ''}`)) && anteil(soll.get(k), storyText(s)) >= INHALT_MIN);
    if (!traeger) continue;
    traeger.deckt_ab = [...(Array.isArray(traeger.deckt_ab) ? traeger.deckt_ab : []), k];
    ist.add(k);
    weich.push(`Epic ${i + 1}: ${k} steht schon in „${String(traeger.titel || '').slice(0, 60)}“ (im Kriterium genannt), kein Nachauftrag.`);
  }
  // Seit 23.10.2026 (C9, Rest): Ein Akzeptanzkriterium von BC2 (K..) gilt auch
  // ohne Nummer als abgedeckt, wenn eine Story es nahezu wörtlich als Kriterium
  // führt (Anteil der Wörter ab 0,8). Lauf 2516: K2 bis K6 standen wörtlich in
  // den Stories 2 bis 5, der Story-Ergänzer schrieb trotzdem sechs Stories dazu.
  // Gemessen an 2259, 2261 und 2516: echte Treffer 1,0, das nächstbeste
  // Kriterium höchstens 0,63. Nur für K, bei den Anforderungen (A) streut es zu stark.
  const WOERTLICH_AB = 0.8;
  (ein.akzeptanzkriterien_geschaeftlich || []).forEach((x, n) => {
    const k = `K${n + 1}`;
    if (ist.has(k)) return;
    const kriterium = typeof x === 'string' ? x : (x?.kriterium || '');
    let best = 0, traeger = null;
    for (const s of e.stories || []) for (const a of s.akzeptanzkriterien || []) {
      const w = anteil(kriterium, a.text || '');
      if (w > best) { best = w; traeger = s; }
    }
    if (!traeger || best < WOERTLICH_AB) return;
    traeger.deckt_ab = [...(Array.isArray(traeger.deckt_ab) ? traeger.deckt_ab : []), k];
    ist.add(k);
    weich.push(`Epic ${i + 1}: ${k} steht schon fast wörtlich in „${String(traeger.titel || '').slice(0, 60)}“ (${Math.round(best * 100)} %), kein Nachauftrag.`);
  });
  const fehlt = [...soll.keys()].filter(k => !ist.has(k));
  // Beansprucht, aber inhaltlich kaum enthalten: bester Anteil ueber alle
  // Stories, die die Nummer nennen.
  const schwach = {};
  const schwach_bei = {};
  for (const k of soll.keys()) {
    if (!ist.has(k)) continue;
    const kandidaten = (e.stories || []).filter(s => (s.deckt_ab || []).map(x => String(x).trim().toUpperCase()).includes(k));
    let best = 0, titel = kandidaten[0]?.titel || '', sid = kandidaten[0]?.story_id;
    for (const s of kandidaten) { const w = anteil(soll.get(k), storyText(s)); if (w > best) { best = w; titel = s.titel; sid = s.story_id; } }
    if (best < INHALT_MIN) schwach_bei[k] = sid;
    if (best < INHALT_MIN) schwach[k] = `von „${titel}“ beansprucht, dort aber kaum enthalten (${Math.round(best * 100)} %)`;
  }
  const nummern = [...fehlt, ...Object.keys(schwach)];
  if (nummern.length) {
    luecken.push({ epic_index: i, nummern, texte: Object.fromEntries(nummern.map(k => [k, soll.get(k)])),
                   inhaltlich_schwach: schwach, schwach_bei });
  }
  const fremd = [...ist].filter(k => !soll.has(k));
  if (fremd.length) weich.push(`Epic ${i + 1}: deckt_ab nennt ${fremd.join(', ')}, die es im Eingang nicht gibt.`);
});

if (hart.length) {
  throw new Error('Vollständigkeitsprüfung fehlgeschlagen: ' + hart.join(' | '));
}

return [{
  json: {
    ...a,
    luecken,
    luecken_anzahl: luecken.reduce((s, l) => s + l.nummern.length, 0),
    // Fuer die Gate-2-Tabelle in BC3-00: die Vorgaben je Epic (Index = Epic).
    vorgaben_je_epic: eingaenge.map(e => e.bc3_vorgaben || []),
    pruefung_vollstaendigkeit: {
      potenziale: eingaenge.length,
      epics: a.anzahl_epics,
      stories: storiesGesamt,
      anforderungen_im_eingang: anfGesamt,
      akzeptanzkriterien_im_eingang: akzGesamt,
      vorgaben_bc3: vorgGesamt,
      stories_ohne_kriterium: ohneKriterium,
      befunde: [...(eingaenge[0]?.eingang_befunde || []), ...weich],
    },
  },
}];

const a = $input.first().json;
const rein = $('Vom Orchestrator aufgerufen').first().json;
const u = rein.umschlag || {};
const p = a.pruefung_vollstaendigkeit || {};

/**
 * Welche Sprachmodelle haben geschnitten? (seit 12.10.2026)
 *
 * Gelesen wird die Einstellung des Modell-Bausteins. Die Regel fuer BC3 lautet
 * Mistral mit fester Version; OpenAI ist nur fuer Tests zugelassen (Svetlana
 * 11.10.2026). Gate 2 zeigt die Liste an und warnt bei Abweichung.
 */
function modellVon(namen) {
  for (const n of namen) {
    try {
      const pa = $(n).params || {};
      const m = pa.model ?? pa.modelName;
      const name = (m && typeof m === 'object') ? (m.value || m.cachedResultName) : m;
      if (name) return { baustein: n, modell: String(name) };
    } catch (e) { /* Baustein gibt es nicht */ }
  }
  return { baustein: null, modell: 'unbekannt' };
}
let ergaenzerLief = false;
try { ergaenzerLief = $('Story-Ergänzer').all().length > 0; } catch (e) { ergaenzerLief = false; }
const modelle = [
  { schritt: 'Story-Architekt', ...modellVon(['OpenAI Chat Model', 'Mistral Cloud Chat Model', 'Mistral Chat Model']) },
  ...(ergaenzerLief
    ? [{ schritt: 'Story-Ergänzer', ...modellVon(['OpenAI Chat Model 2', 'Mistral Cloud Chat Model 2', 'Mistral Chat Model 2']) }]
    : []),
];

// Was „Kriterien reparieren“ und „Ergänzung bereinigen“ geändert haben (seit 22.10.2026)
const reparaturen = [];
for (const n of ['Kriterien reparieren', 'Ergänzung bereinigen']) {
  try { for (const i of $(n).all()) reparaturen.push(...(i.json.reparatur || [])); } catch (e) { /* lief nicht */ }
}

// Kennzeichnung einer Simulation bleibt im Epic-Titel, damit sie bis ins Ticket-Set sichtbar ist.
// Epic i gehört zu Potenzial i, außer das Epic nennt sein Potenzial selbst.
const MARKER = '[SIMULIERT]';
const pots = u.potenziale || [];
let markiert = 0;
const epics = (a.epics || []).map((e, i) => {
  const pot = pots.find(x => e.use_case_id_ref && String(x.use_case_id) === String(e.use_case_id_ref)) || pots[i] || {};
  const titel = String(e.titel || '');
  if (!String(pot.use_case_titel || '').startsWith(MARKER) || titel.startsWith(MARKER)) return e;
  markiert++;
  return { ...e, titel: `${MARKER} ${titel}` };
});

return [{
  json: {
    lauf_id: rein.lauf_id,
    umschlag: {
      ...u,
      aggregat: { ...a, epics },
      epics,
      protokoll: [...(u.protokoll || []), {
        stufe: 'BC3-20 Stories schneiden',
        zeitpunkt: new Date().toISOString(),
        status: 'ok',
        umfang: { epics: p.epics, stories: p.stories },
        modelle,
        befunde: [...(p.befunde || []), ...reparaturen,
          ...(markiert ? [`Kennzeichnung ${MARKER} aus dem Konzept an ${markiert} Epics übernommen`] : [])],
      }],
    },
  },
}];

/**
 * Ein Item je Epic mit Lücken. Der Story-Ergänzer sieht die vorhandenen
 * Stories nur als Titel mit deckt_ab - er soll sie nicht neu schreiben,
 * sondern nur das Fehlende nachliefern.
 *
 * Seit 12.10.2026 auch fuer Nummern, die eine Story nur behauptet: dann steht
 * der Grund dabei, damit der Ergaenzer weiss, warum die vorhandene Story nicht
 * zaehlt.
 *
 * Seit 13.10.2026 steht bei schwachen Nummern der volle Text der Story dabei
 * (zu_pruefen). Steht der Inhalt doch drin, nur mit anderen Worten, darf der
 * Ergaenzer die Nummer mit einem woertlichen Satz aus der Story bestaetigen,
 * statt eine neue Story zu schreiben. 'Ergänzung einfügen' prueft den Satz.
 */
const a = $input.first().json;
const eingaenge = $('Potenziale auspacken').all().map(i => i.json);

return (a.luecken || []).map(l => {
  const e = (a.epics || [])[l.epic_index] || {};
  const p = eingaenge[l.epic_index] || {};
  const st = e.stories || [];
  const grund = l.inhaltlich_schwach || {};
  const bei = l.schwach_bei || {};
  const volltext = s => [`${s.story_id}: ${s.titel}`, s.beschreibung,
    ...(s.akzeptanzkriterien || []).map(k => `- ${k.text || ''}${k.messverfahren ? ` (Messverfahren: ${k.messverfahren})` : ''}`)].join('\n');
  return {
    json: {
      epic_index: l.epic_index,
      epic_id: e.epic_id,
      use_case_titel: p.use_case_titel,
      fachliche_beschreibung: p.fachliche_beschreibung,
      to_be_vision: p.to_be_vision,
      vorhandene_stories: st.map(s => `${s.story_id}: ${s.titel} [${(s.deckt_ab || []).join(', ')}]`).join('\n'),
      fehlend: l.nummern.map(k => `${k}: ${l.texte[k]}${grund[k] ? `\n   (Bisher ${grund[k]}. Diese Zuordnung zählt nicht.)` : ''}`).join('\n'),
      zu_pruefen: Object.keys(grund).map(k => {
        const s = st.find(x => x.story_id === bei[k]);
        return s ? `${k}, beansprucht von:\n${volltext(s)}` : null;
      }).filter(Boolean).join('\n\n'),
      // Seit 13.10.2026: Lauf 431 hat gezeigt, dass der Ergaenzer nur behauptete
      // Nummern sonst uebergeht. Die Liste steht deshalb noch einmal ausdruecklich da.
      pflicht: l.nummern.join(', '),
      // Seit 22.10.2026: nach der höchsten Nummer, nicht nach der Anzahl. "Vollständigkeit
      // prüfen" entfernt Stories ohne Kriterium, sonst gäbe es eine Kennung doppelt.
      naechste_nummer: Math.max(st.length, ...st.map(s => Number(String(s.story_id || '').match(/-(\d+)$/)?.[1] || 0))) + 1,
    },
  };
});

