Die erste neue story_id ist {{ $json.epic_id }}-{{ $json.naechste_nummer }}.

parameters.jsCode:
/**
 * Hängt die Stories des zweiten Durchgangs an und prüft die Abdeckung erneut.
 * Fehlt dann immer noch eine Nummer, bricht der Lauf ab - mit einer Meldung in
 * EINER Zeile, damit sie im Umschlag des Orchestrators lesbar ankommt.
 *
 * Seit 12.10.2026: Nummern, die nur inhaltlich schwach abgedeckt waren, werden
 * nach dem zweiten Durchgang erneut gemessen. Bleiben sie schwach, ist das ein
 * weicher Befund (Gate 2 zeigt ihn), kein Abbruch - die Messung ist eine
 * Wortregel und darf allein keine Lieferung kippen.
 *
 * Seit 13.10.2026 darf der Ergaenzer eine schwache Nummer bestaetigen:
 * bestaetigt: [{ nr, story_id, satz }]. Sie zaehlt nur, wenn die Story die
 * Nummer beansprucht und der Satz dort woertlich steht (mind. 20 Zeichen).
 * Gate 2 sieht den Satz als Befund. Fuer fehlende Nummern gilt das nicht.
 */
const a = $('Vollständigkeit prüfen').first().json;
const auftraege = $('Nachauftrag bauen').all().map(i => i.json);
const antworten = $input.all();
const epics = JSON.parse(JSON.stringify(a.epics || []));
const hart = [];
const weich = [];
const nachgebessert = [];

// --- Inhaltlicher Abgleich ueber Wortteile (seit 12.10.2026) ----------------
// DIESELBE Regel steht in BC3-00 'Abdeckung anhaengen' (Gate-2-Tabelle).
// Wer sie aendert, aendert sie an beiden Stellen - sonst meldet Gate 2 etwas
// anderes als die Vollstaendigkeitspruefung.
const FUELL = new Set(['eine', 'einer', 'einem', 'einen', 'eines', 'wird', 'werden', 'wurde', 'nicht',
  'oder', 'sowie', 'dass', 'wenn', 'dann', 'sind', 'ihre', 'ihren', 'alle', 'allen', 'mehr', 'nach',
  'ueber', 'über', 'durch', 'beim', 'given', 'when', 'then', 'gegeben', 'diese', 'dieser', 'dieses',
  'kann', 'muss', 'soll', 'damit', 'auch', 'noch', 'sich', 'etwa', 'jede', 'jeder', 'jedes', 'mindestens',
  'system', 'systems', 'story']);
const woerter = s => [...new Set(String(s || '').toLowerCase()
  .replace(/ß/g, 'ss')
  .replace(/[^a-zäöü0-9 ]+/g, ' ').split(/\s+/)
  .filter(x => x.length > 3 && !FUELL.has(x)))];
const DREIER = new Map();
const dreierVon = w => {
  if (!DREIER.has(w)) { const s = ` ${w} `; const g = new Set(); for (let i = 0; i < s.length - 2; i++) g.add(s.slice(i, i + 3)); DREIER.set(w, g); }
  return DREIER.get(w);
};
function wortGleich(a, b) {
  if (a === b) return true;
  if (Math.min(a.length, b.length) >= 5 && (a.startsWith(b) || b.startsWith(a))) return true;
  // Wortende (seit 13.10.2026): Zusammensetzungen wie 'Vorschlagsliste' / 'Liste'.
  if (Math.min(a.length, b.length) >= 5 && (a.endsWith(b) || b.endsWith(a))) return true;
  const A = dreierVon(a), B = dreierVon(b);
  let g = 0; for (const x of A) if (B.has(x)) g++;
  return (2 * g) / (A.size + B.size) >= 0.6;
}
function anteil(quelle, ziel) {
  const q = woerter(quelle), z = woerter(ziel);
  if (!q.length) return 1;
  let treffer = 0;
  for (const w of q) if (z.some(x => wortGleich(w, x))) treffer++;
  return treffer / q.length;
}
const storyText = s => [s.titel, s.beschreibung,
  ...(s.akzeptanzkriterien || []).map(k => `${k.text || ''} ${k.messverfahren || ''}`)].join(' ');
// Unter diesem Anteil gilt eine beanspruchte Nummer als inhaltlich NICHT
// abgedeckt und geht an den Story-Ergaenzer. Geeicht an den Laeufen 388, 395,
// 402 und 419: echte Fehlzuordnungen lagen bei 0-17 %, tragfaehige ab 29 %.
const INHALT_MIN = 0.2;

const norm = t => String(t || '').toLowerCase().replace(/ß/g, 'ss')
  .replace(/[„“”"'‚‘’«»]/g, '').replace(/\s+/g, ' ').trim();

antworten.forEach((it, n) => {
  const auftrag = auftraege[n];
  if (!auftrag) return;
  const nr = auftrag.epic_index + 1;
  const l = (a.luecken || []).find(x => x.epic_index === auftrag.epic_index);
  let neu = [];
  let bestaetigt = [];
  try {
    const roh = String(it.json.output || '').trim()
      .replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```\s*$/i, '').trim();
    const j = JSON.parse(roh);
    neu = Array.isArray(j) ? j : (j.stories || []);
    bestaetigt = Array.isArray(j) ? [] : (Array.isArray(j.bestaetigt) ? j.bestaetigt : []);
  } catch (e) {
    hart.push(`Epic ${nr}: Antwort des Story-Ergänzers nicht lesbar (${e.message})`);
    return;
  }
  // Seit 22.10.2026 (Vorschlag 4, Lauf 852): Stories des Ergänzers ohne Titel,
  // Beschreibung oder Kriterium verwerfen. Fehlt ihre Nummer danach, bricht der
  // Lauf unten ab wie jede andere Lücke (R6 in BC3-00 wiederholt BC3-20).
  neu = neu.filter(s => {
    const k = (s?.akzeptanzkriterien || []).filter(x => x && typeof x === 'object' && String(x.text || '').trim());
    if (s && String(s.titel || '').trim() && String(s.beschreibung || '').trim() && k.length) return true;
    weich.push(`Epic ${nr}: Story des Ergänzers ohne ${!String(s?.titel || '').trim() ? 'Titel'
      : !String(s?.beschreibung || '').trim() ? 'Beschreibung' : 'Kriterium'} verworfen (${String(s?.story_id || '?')}).`);
    return false;
  });
  const epic = epics[auftrag.epic_index];
  epic.stories = [...(epic.stories || []), ...neu];
  const anspruch = s => (s.deckt_ab || []).map(x => String(x).trim().toUpperCase());
  const ist = new Set(epic.stories.flatMap(anspruch));
  const schwachVorher = l.inhaltlich_schwach || {};
  const fehlt = l.nummern.filter(k => !ist.has(k));
  const nochSchwach = l.nummern.filter(k => ist.has(k) && schwachVorher[k]).filter(k => {
    const best = epic.stories.filter(s => anspruch(s).includes(k))
      .reduce((m, s) => Math.max(m, anteil(l.texte[k], storyText(s))), 0);
    if (best >= INHALT_MIN) return false;
    const b = bestaetigt.find(x => String(x?.nr || '').trim().toUpperCase() === k);
    if (!b) {
      if (!neu.some(s => anspruch(s).includes(k))) weich.push(`Epic ${nr}: ${k} vom Story-Ergänzer übergangen (keine neue Story, keine Bestätigung).`);
      return true;
    }
    const s = epic.stories.find(x => x.story_id === b.story_id);
    const satz = norm(b.satz);
    if (s && anspruch(s).includes(k) && satz.length >= 20 && norm(storyText(s)).includes(satz)) {
      weich.push(`Epic ${nr}: ${k} vom Story-Ergänzer bestätigt mit „${String(b.satz).trim().slice(0, 160)}“ (${s.story_id}) - an Gate 2 prüfen.`);
      return false;
    }
    weich.push(`Epic ${nr}: Bestätigung für ${k} ungültig (Satz steht nicht wörtlich in ${b.story_id || 'der Story'} oder Story beansprucht ${k} nicht).`);
    return true;
  });
  if (fehlt.length) {
    hart.push(`Epic ${nr}: nach zweitem Durchgang fehlt `
      + fehlt.map(k => `${k} "${String(l.texte[k] || '').slice(0, 80)}"`).join('; '));
  } else {
    const neuNr = new Set(neu.flatMap(anspruch));
    const ergaenzt = l.nummern.filter(k => neuNr.has(k));
    if (ergaenzt.length) nachgebessert.push(`Epic ${nr}: ${ergaenzt.join(', ')} im zweiten Durchgang ergänzt (${neu.length} Story(s))`);
  }
  if (nochSchwach.length) {
    weich.push(`Epic ${nr}: ${nochSchwach.join(', ')} auch nach dem zweiten Durchgang inhaltlich schwach abgedeckt - an Gate 2 prüfen.`);
  }
});

if (hart.length) {
  throw new Error('Vollständigkeitsprüfung fehlgeschlagen: ' + hart.join(' | '));
}

const p = a.pruefung_vollstaendigkeit || {};
return [{
  json: {
    ...a,
    epics,
    luecken: [],
    luecken_anzahl: 0,
    pruefung_vollstaendigkeit: {
      ...p,
      stories: epics.reduce((s, e) => s + (e.stories || []).length, 0),
      nachgebessert,
      befunde: [...(p.befunde || []), ...nachgebessert, ...weich],
    },
  },
}];

// Kriterien, die das Modell nur als Nummer ("K2") oder ganz ohne Inhalt schreibt, reparieren (seit 22.10.2026, Läufe 934 und 972)
// Mit Messverfahren von BC2: Kriterium einsetzen und K in deckt_ab. Ohne: Verweis entfernen,
// die Vollständigkeitsprüfung schickt die Nummer dann an den Story-Ergänzer.
const ein = $('Potenziale auspacken').all().map(i => i.json);

function lesen(roh) {
  const t = String(roh || '').trim()
    .replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```\s*$/i, '').trim();
  try { return JSON.parse(t); } catch (e) { return null; }
}

// Fehlt ein Messverfahren, bleibt es offen (nichts erfinden, Punkt 25), BC3-40 bricht dann nicht ab
const OFFEN = 'offen: kein Messverfahren im Konzept';

// Messverfahren nur aus dem Input: BC2-Kriterien und Vorgaben von BC3 (seit 22.10.2026, Lauf 1309)
// Wortabgleich, Schwelle 0,6 an den Läufen 1252, 1307, 1309 getestet
const SCHWELLE = 0.6;
function woerter(t) {
  return new Set(String(t || '').toLowerCase()
    .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss')
    .replace(/[^a-z0-9 ]+/g, ' ').split(/\s+/).filter(w => w.length >= 4));
}
function anteil(m, refs) {
  const w = woerter(m);
  if (!w.size) return 0;
  let best = 0;
  for (const r of refs) {
    const rw = woerter(r);
    let n = 0;
    for (const x of w) if (rw.has(x)) n++;
    best = Math.max(best, n / w.size);
  }
  return best;
}
function abgleichen(k, s, ks, refs, meldungen) {
  const m = String(k.messverfahren || '');
  if (/^offen:/i.test(m)) return k;
  const aus = m.match(/^\s*Messverfahren aus K(\d+)\s*:/i);
  const bc2 = aus ? ks[Number(aus[1]) - 1] : null;
  if (bc2 && typeof bc2 === 'object' && bc2.messverfahren) {
    meldungen.push(`${s.story_id || 'Story'}: Messverfahren auf das von BC2 zu K${aus[1]} gesetzt`);
    return { ...k, messverfahren: bc2.messverfahren };
  }
  if (anteil(m, refs) >= SCHWELLE) return k;
  meldungen.push(`${s.story_id || 'Story'}: Messverfahren nicht im Input, als offen markiert („${m.slice(0, 80)}“)`);
  return { ...k, messverfahren: OFFEN };
}

function reparieren(stories, potenzial) {
  const ks = potenzial?.akzeptanzkriterien_geschaeftlich || [];
  const refs = [
    ...ks.map(a => (a && typeof a === 'object' ? a.messverfahren : null)).filter(Boolean),
    ...(potenzial?.bc3_vorgaben || []).map(v => v.text),
  ];
  const meldungen = [];
  for (const s of stories || []) {
    if (!Array.isArray(s.akzeptanzkriterien)) continue;
    const neu = [];
    for (const k of s.akzeptanzkriterien) {
      if (k && typeof k === 'object') {
        let o = { ...k };
        if (!o.text && o.kriterium) { o.text = o.kriterium; delete o.kriterium; }
        // Kriterium unter einem Satz als Feldname verschachtelt (seit 23.10.2026, Lauf 2442): auspacken
        if (!o.text) {
          const innen = Object.entries(o).find(([, v]) => v && typeof v === 'object' && typeof v.text === 'string');
          if (innen) {
            o = { text: innen[1].text, messverfahren: innen[1].messverfahren || o.messverfahren };
            meldungen.push(`${s.story_id || 'Story'}: verschachteltes Kriterium ausgepackt („${innen[0].slice(0, 60)}“)`);
          }
        }
        // Nur text und messverfahren sind im Vertrag erlaubt
        const fremd = Object.keys(o).filter(x => !['text', 'messverfahren'].includes(x));
        if (fremd.length) {
          fremd.forEach(x => delete o[x]);
          meldungen.push(`${s.story_id || 'Story'}: Felder ${fremd.join(', ')} am Kriterium entfernt`);
        }
        // Ohne Text kein Kriterium (wie bei Nummern ohne Inhalt)
        if (String(o.text || '').trim().length < 10) {
          meldungen.push(`${s.story_id || 'Story'}: Kriterium ohne Text entfernt`);
          continue;
        }
        if (String(o.messverfahren || '').trim().length < 5) {
          o.messverfahren = OFFEN;
          meldungen.push(`${s.story_id || 'Story'}: Kriterium ohne Messverfahren, als offen markiert`);
        }
        neu.push(o);
        continue;
      }
      const roh = typeof k === 'string' ? k.trim() : '';
      const m = roh.match(/^K(\d+)$/i);
      if (!m) {
        // Satz ohne Messverfahren: als Objekt mit offenem Messverfahren (seit 22.10.2026, Lauf 1295)
        if (roh.length >= 10 && !/^[AV]\d+$/i.test(roh)) {
          neu.push({ text: roh, messverfahren: OFFEN });
          meldungen.push(`${s.story_id || 'Story'}: Kriterium als Text, in Objekt mit offenem Messverfahren umgewandelt`);
          continue;
        }
        // ohne Inhalt (Zahl, leer, Verweis wie A3 oder V2): entfernen (seit 22.10.2026, Lauf 972)
        meldungen.push(`${s.story_id || 'Story'}: Kriterium ohne Inhalt (${JSON.stringify(k)}) entfernt`);
        continue;
      }
      const nr = `K${m[1]}`;
      const bc2 = ks[Number(m[1]) - 1];
      if (bc2 && typeof bc2 === 'object' && bc2.kriterium && bc2.messverfahren) {
        neu.push({ text: bc2.kriterium, messverfahren: bc2.messverfahren });
        s.deckt_ab = [...new Set([...(s.deckt_ab || []), nr])];
        meldungen.push(`${s.story_id || 'Story'}: Kriterium „${nr}“ durch das Kriterium von BC2 ersetzt`);
      } else if (String(bc2?.kriterium || bc2 || '').trim().length >= 10) {
        neu.push({ text: String(bc2?.kriterium || bc2).trim(), messverfahren: OFFEN });
        s.deckt_ab = [...new Set([...(s.deckt_ab || []), nr])];
        meldungen.push(`${s.story_id || 'Story'}: Kriterium „${nr}“ durch das Kriterium von BC2 ersetzt, Messverfahren offen`);
      } else {
        meldungen.push(`${s.story_id || 'Story'}: Verweis „${nr}“ ohne Kriterium entfernt`);
      }
    }
    s.akzeptanzkriterien = neu.map(k => abgleichen(k, s, ks, refs, meldungen));
  }
  return meldungen;
}

return $input.all().map((it, i) => {
  const j = lesen(it.json.output);
  if (!j) return it;   // unlesbar, das meldet „Epics aggregieren“
  const reparatur = reparieren(j.stories, ein[i]);
  if (!reparatur.length) return it;
  return { json: { ...it.json, output: JSON.stringify(j), reparatur }, pairedItem: it.pairedItem };
});

