return $input.all().map((it, i) => {
  const j = lesen(it.json.output);
  if (!j) return it;   // unlesbar, das meldet „Ergänzung einfügen“
  const auftrag = auftraege[i] || {};
  const reparatur = reparieren(j.stories, ein[auftrag.epic_index]);
  const erlaubt = new Set(String(auftrag.pflicht || '').split(/[,\s]+/).filter(Boolean).map(x => x.toUpperCase()));
  for (const s of j.stories || []) {
    if (!Array.isArray(s.deckt_ab) || !erlaubt.size) continue;
    const weg = s.deckt_ab.filter(x => !erlaubt.has(String(x).trim().toUpperCase()));
    if (!weg.length) continue;
    s.deckt_ab = s.deckt_ab.filter(x => erlaubt.has(String(x).trim().toUpperCase()));
    reparatur.push(`${s.story_id || 'Story'}: nicht angefragte Nummern gestrichen (${weg.join(', ')})`);
  }
  if (!reparatur.length) return it;
  return { json: { ...it.json, output: JSON.stringify(j), reparatur }, pairedItem: it.pairedItem };
});
